const setVars = $('Set Variables').first().json;
const chatId = setVars.chat_id;
const textoUsuario = setVars.texto_usuario;
const nombreUsuario = setVars.nombre_usuario;

let historialItems = [];
try {
  historialItems = $('Leer Historial').all();
} catch (e) {
  historialItems = [];
}

let stockItems = [];
try {
  stockItems = $('Leer Stock Propiedades')
    .all()
    .map((item) => item.json)
    .filter(
      (row) =>
        row &&
        typeof row === 'object' &&
        !(
          typeof row.error === 'string' &&
          /authorization grant|invalid_grant|token is invalid|OAuth2/i.test(row.error)
        ) &&
        !(Object.keys(row).length === 1 && Object.prototype.hasOwnProperty.call(row, 'error')),
    );
} catch (e) {
  stockItems = [];
}

function rowToStockLine(row) {
  const id = row.id ?? row.ID ?? row.codigo ?? '';
  const tipo = row.tipo ?? row.Tipo ?? row.tipologia ?? '';
  const zona = row.zona ?? row.Zona ?? row.barrio ?? '';
  const precio = row.precio ?? row.Precio ?? row.precio_usd ?? '';
  const desc = row.descripcion ?? row.Descripcion ?? row.detalle ?? '';
  const estado = row.estado ?? row.Estado ?? row.stock ?? 'disponible';
  const bits = [tipo, zona, precio ? String(precio) : '', desc].filter(Boolean);
  const head = id ? '[' + id + '] ' : '';
  return head + bits.join(' | ') + (estado ? ' (' + estado + ')' : '');
}

let stockText = '';
if (stockItems.length) {
  stockText = stockItems.map(rowToStockLine).map((l) => '- ' + l).join('\n');
} else {
  stockText =
    '- (Sin filas en la planilla de stock (propiedades) o no se pudo leer. Ofrece ayuda humana o pedir cargar stock.)';
}

const matchRow = historialItems.find(
  (item) => item.json && String(item.json.chat_id) === String(chatId),
);
const historialItemsFiltered = matchRow ? [matchRow] : [];

let historialJson = [];
let turno = 1;
let rowExists = false;
let propiedadSeguimientoPrev = '';
let ultimaActualizacionStr = '';
let diasSinContacto = 0;

if (historialItemsFiltered.length > 0 && historialItemsFiltered[0].json && historialItemsFiltered[0].json.chat_id) {
  const row = historialItemsFiltered[0].json;
  rowExists = true;
  turno = parseInt(row.turno || 0) + 1;
  propiedadSeguimientoPrev = String(row.propiedad_seguimiento || '').trim();
  ultimaActualizacionStr = String(row.ultima_actualizacion || '').trim();
  try {
    historialJson = JSON.parse(row.historial_json || '[]');
  } catch (e) {
    historialJson = [];
  }
  if (ultimaActualizacionStr) {
    const t = new Date(ultimaActualizacionStr);
    if (!isNaN(t.getTime())) {
      diasSinContacto = Math.floor((Date.now() - t.getTime()) / 86400000);
    }
  }
}

let refSeg = '';
if (propiedadSeguimientoPrev) {
  try {
    const o = JSON.parse(propiedadSeguimientoPrev);
    if (o && typeof o === 'object' && o.referencia) refSeg = String(o.referencia);
    else if (o && typeof o === 'object' && o.id) refSeg = String(o.id);
  } catch (e) {
    refSeg = propiedadSeguimientoPrev.length > 120 ? propiedadSeguimientoPrev.slice(0, 117) + '…' : propiedadSeguimientoPrev;
  }
}

const contextoCliente =
  '- Días aproximados desde el último registro en CRM (ultima_actualizacion): ' +
  (ultimaActualizacionStr ? diasSinContacto : 'sin_dato') +
  '\n' +
  '- Propiedad en seguimiento guardada (si existe): ' +
  (refSeg || '(ninguna)') +
  '\n' +
  '- Si hay varios días sin contacto y hay propiedad en seguimiento, está bien retomar con una sola frase breve y cordial al inicio; no insistir ni presionar.';

const systemPrompt =
  'Sos Matías, asesor inmobiliario de Nodo Propiedades (Argentina). Tu trabajo es solo atender consultas sobre inmuebles: disponibilidad, precios en el stock, zonas, tipología, visitas y derivaciones relacionadas con el catálogo.\n\n' +
  'ALCANCE: Si el mensaje no tiene relación con inmuebles o el stock (otros temas, bromas, política, tecnología, vida personal, etc.), respondé en 1–2 frases cordiales y profesionales aclarando que solo podés orientar sobre propiedades y el catálogo, y ofrecé continuar si tiene una consulta inmobiliaria. No des datos ni opiniones fuera de ese marco.\n\n' +
  'PROHIBICIÓN ESTRICTA: No uses en ningún caso la palabra "che" (ni como saludo ni como interjección). Usá un trato profesional directo: "Hola", "Buenos días", o el nombre si lo tenés.\n\n' +
  'CONTEXTO_CLIENTE (uso interno; no lo repitas literal ni digas que venís de un CRM):\n' +
  contextoCliente +
  '\n\n' +
  'SEGUIMIENTO EN CONVERSACIÓN:\n' +
  '- Si CONTEXTO_CLIENTE muestra ~3 días o más sin registro previo y había propiedad en seguimiento, podés empezar con UNA sola línea corta retomando el interés; después respondé al mensaje actual.\n' +
  '- No hagas seguimiento agresivo: una mención suave; si el cliente cambió de tema, priorizá lo que preguntó ahora.\n\n' +
  'STOCK (solo ofrecé propiedades de esta lista; si no hay match, ofrecé las más cercanas o pedí más datos):\n' +
  stockText +
  '\n\n' +
  'ESTILO Y FORMATO:\n' +
  '- Español claro, profesional y cercano (podés usar voseo si resulta natural).\n' +
  '- Cuando convenga, ordená la respuesta con viñetas o pasos breves; evitá muros de texto largos en Telegram.\n' +
  '- Priorizá una intención o una pregunta por mensaje cuando pida información al cliente.\n' +
  '- No inventes inmuebles fuera del stock; podés parafrasear la lista.\n\n' +
  'PROPIEDAD EN SEGUIMIENTO (para recordatorios posteriores):\n' +
  '- Si el usuario se enfoca claramente en UNA propiedad del stock (detalle, visita, reserva, "me interesa la de…"), al FINAL del mensaje agregá exactamente este bloque (una sola línea JSON dentro):\n\n' +
  '###PROPIEDAD_SEGUIMIENTO###\n' +
  '{"id":"id_o_codigo_stock","referencia":"breve texto para recordatorios (zona + tipo o codigo)"}\n' +
  '###FIN_PROP###\n\n' +
  '- Si no hay una propiedad clara o es solo una consulta general, NO incluyas este bloque (deja el seguimiento anterior sin cambios en el sistema).\n\n' +
  'CUANDO TENGAS OPORTUNIDAD DE VENTA (nombre, zona, presupuesto aproximado y compra o alquiler), al FINAL del mensaje (después del bloque de propiedad si lo hubo) pegá exactamente este bloque:\n\n' +
  '  ###LEAD_COMPLETO###\n' +
  '  {"nombre":"...","zona":"...","presupuesto":"...","operacion":"compra|alquiler","temperatura":"caliente|tibio|frio","resumen":"..."}\n' +
  '  ###FIN_LEAD###\n\n' +
  '- temperatura: caliente = urgencia o presupuesto claro; tibio = interés sin fecha; frío = curiosidad.\n' +
  '- Si falta información para cerrar el lead, seguí la conversación SIN el bloque JSON.';

const messages = [{ role: 'system', content: systemPrompt }];

for (const msg of historialJson) {
  messages.push(msg);
}

messages.push({ role: 'user', content: textoUsuario });

return [
  {
    json: {
      chat_id: chatId,
      texto_usuario: textoUsuario,
      nombre_usuario: nombreUsuario,
      messages: messages,
      historial_json: historialJson,
      turno: turno,
      row_exists: rowExists,
      propiedad_seguimiento_actual: propiedadSeguimientoPrev,
      dias_sin_contacto: diasSinContacto,
    },
  },
];

const groqData = $input.first().json;
const promptData = $('Construir Prompt').first().json;

const respuestaCompleta = groqData.choices[0].message.content;
const chatId = promptData.chat_id;
const textoUsuario = promptData.texto_usuario;
const nombreUsuario = promptData.nombre_usuario;
let historialJson = Array.isArray(promptData.historial_json) ? promptData.historial_json : [];
const turno = promptData.turno;
const rowExists = promptData.row_exists;
const propiedadPrevRaw = String(promptData.propiedad_seguimiento_actual || '').trim();

function quitarMuletillaChe(texto) {
  if (!texto || typeof texto !== 'string') return texto;
  let s = texto.replace(/\b[Cc]he\b[,.;:!?]*\s*/g, '');
  s = s.replace(/\s{2,}/g, ' ').trim();
  return s;
}

const leadRegex = /###LEAD_COMPLETO###[\s\S]*?({[\s\S]*?})[\s\S]*?###FIN_LEAD###/;
const propRegex = /###PROPIEDAD_SEGUIMIENTO###[\s\S]*?({[\s\S]*?})[\s\S]*?###FIN_PROP###/;

let working = respuestaCompleta;

const propMatch = working.match(propRegex);
let propiedadSeguimiento = propiedadPrevRaw;

if (propMatch) {
  try {
    const obj = JSON.parse(propMatch[1].trim());
    const idP = obj.id != null ? String(obj.id).trim() : '';
    const refP = obj.referencia != null ? String(obj.referencia).trim() : '';
    if (idP || refP) {
      propiedadSeguimiento = JSON.stringify({ id: idP, referencia: refP });
    } else {
      propiedadSeguimiento = propiedadPrevRaw;
    }
  } catch (e) {
    propiedadSeguimiento = propiedadPrevRaw;
  }
  working = working.replace(/###PROPIEDAD_SEGUIMIENTO###[\s\S]*?###FIN_PROP###/, '').trim();
}

const match = working.match(leadRegex);

let leadCompleto = false;
let leadData = {};
let respuestaBot = working;

if (match) {
  try {
    leadData = JSON.parse(match[1].trim());
    leadCompleto = true;
    respuestaBot = working.replace(/###LEAD_COMPLETO###[\s\S]*?###FIN_LEAD###/, '').trim();
  } catch (e) {
    leadCompleto = false;
  }
}

respuestaBot = quitarMuletillaChe(respuestaBot);

historialJson.push({ role: 'user', content: textoUsuario });
historialJson.push({ role: 'assistant', content: respuestaBot });

if (historialJson.length > 40) {
  historialJson = historialJson.slice(historialJson.length - 40);
}

const ahora = new Date().toISOString();

return [
  {
    json: {
      chat_id: chatId,
      nombre_usuario: nombreUsuario,
      lead_completo: leadCompleto,
      respuesta_bot:
        respuestaBot ||
        'Hola, soy Matías de Nodo Propiedades. ¿En qué puedo ayudarte con propiedades o el catálogo?',
      historial_json: JSON.stringify(historialJson),
      turno: turno,
      row_exists: rowExists,
      fecha: ahora,
      nombre: leadData.nombre || nombreUsuario,
      zona: leadData.zona || '',
      presupuesto: leadData.presupuesto || '',
      tipo_operacion: leadData.operacion || '',
      temperatura: leadData.temperatura || '',
      resumen: leadData.resumen || '',
      propiedad_seguimiento: propiedadSeguimiento,
    },
  },
];
